// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address currentOwner = c.owner();
        vm.prank(caller);
        bool success;
        try c.setOwner(address(0xdead)) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }
        assertTrue(success == (caller == currentOwner));
    }
}
